package com.example.mydailyroutine;
import android.app.*;import android.content.*;import java.util.*;
public class ReminderScheduler {
 static void scheduleAll(Context c){String[] ns=c.getSharedPreferences("routine_data",0).getString("names",String.join("|",new String[]{"Wake up","Drink water","Exercise","Take tablet","Drink water","Drink water","Evening walk","Sleep"})).split("\\|",-1);String[] ts=c.getSharedPreferences("routine_data",0).getString("times",String.join("|",new String[]{"06:00","07:00","07:30","09:00","11:00","14:00","18:00","22:30"})).split("\\|",-1);for(int i=0;i<Math.min(ns.length,ts.length);i++)try{String[] p=ts[i].split(":");schedule(c,ns[i],Integer.parseInt(p[0]),Integer.parseInt(p[1]),i);}catch(Exception ignored){}}
 static void schedule(Context c,String title,int h,int m,int id){Calendar cal=Calendar.getInstance();cal.set(Calendar.HOUR_OF_DAY,h);cal.set(Calendar.MINUTE,m);cal.set(Calendar.SECOND,0);if(cal.getTimeInMillis()<=System.currentTimeMillis())cal.add(Calendar.DAY_OF_YEAR,1);Intent in=new Intent(c,ReminderReceiver.class).putExtra("title",title).putExtra("hour",h).putExtra("minute",m).putExtra("id",id);PendingIntent pi=PendingIntent.getBroadcast(c,id,in,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),pi);}
}
